package local.mediacenter.library
import org.json.*
import java.io.ByteArrayOutputStream
import java.util.zip.*
import org.junit.Test
import org.junit.Assert.*

class BackupTest {
 private fun root()=JSONObject().put("formatVersion",1).put("accounts",JSONArray().put(JSONObject().put("id","fixture").put("type","navidrome").put("name","Fictional library").put("url","https://fixture.invalid").put("username","fixture").put("password","fictional-secret"))).put("preferences",JSONObject().apply{for(p in BackupData.preferences)put(p,JSONObject())}).put("tables",JSONObject().apply{for(t in BackupData.tables)put(t.name,JSONArray())}).put("assets",JSONArray())
 private fun zip(vararg entries:Pair<String,String>):ByteArray {val out=ByteArrayOutputStream();ZipOutputStream(out).use{z->for((name,text)in entries){z.putNextEntry(ZipEntry(name));z.write(text.toByteArray());z.closeEntry()}};return out.toByteArray()}
 @Test fun independentUnicodePasswordVectorIsPortable(){val vector=java.util.Base64.getDecoder().decode("TUNCQUNLVVAxAAECAwQFBgcICQoLDA0ODxAREhMUFRYXGBkaG76wx73quBpTZaypJNxl6kXzHOIvmP/fnLUIKILpULmHM2JVyNfgDrcrncNwGYyLaA==");assertEquals("Media Center portable backup ✓",String(BackupCipher.decrypt(vector,"fixture-pässword-测试".toCharArray()),Charsets.UTF_8))}
 @Test fun incompleteConnectionRecordsFailBeforeRestore(){for(k in listOf("name","username","password")){val r=root();r.getJSONArray("accounts").getJSONObject(0).remove(k);assertTrue(runCatching{BackupData.validate(r)}.isFailure)}}
 @Test fun invalidTransferPoliciesAndRadioOriginsAreNotRestored(){val r=root();r.getJSONObject("preferences").getJSONObject("media_downloads").put("policy","invalid");assertTrue(runCatching{BackupData.validate(r)}.isFailure);val bad=root();bad.getJSONObject("preferences").getJSONObject("device_library").put("stations",JSONArray().put(JSONObject().put("id","a").put("title","Bad").put("url","file:///bad")).toString());assertTrue(runCatching{BackupData.validate(bad)}.isFailure)}
 @Test fun podcastRulesAndEntriesCannotChangeTheirMediaIdentity(){val r=root();r.getJSONObject("tables").getJSONArray("rules").put(JSONArray(listOf("wrong","fixture","show",PodcastInboxRule("fixture","show","Show").json().toString(),0,"")));assertTrue(runCatching{BackupData.validate(r)}.isFailure);val bad=root();bad.getJSONObject("tables").getJSONArray("inbox").put(JSONArray(listOf("wrong","fixture","show","episode",JSONObject().put("kind","book").put("account","fixture").put("show","show").put("episode","episode").toString(),"",0,0,0,"","","",0)));assertTrue(runCatching{BackupData.validate(bad)}.isFailure)}
 @Test fun encryptedBackupRoundTripsWithNoPlaintextCredentials(){val payload=BackupArchive.pack(root(),mapOf("spoken-transcripts/fixture.txt" to "A fictional transcript".toByteArray()));val key="fixture-backup-password".toCharArray();val encrypted=BackupCipher.encrypt(payload,key);assertFalse(String(encrypted,Charsets.ISO_8859_1).contains("fictional-secret"));val parsed=BackupArchive.unpack(BackupCipher.decrypt(encrypted,key));assertEquals("fixture",parsed.manifest.getJSONArray("accounts").getJSONObject(0).getString("id"));assertEquals("A fictional transcript",String(parsed.assets.getValue("spoken-transcripts/fixture.txt")))}
 @Test fun independentExportsUseDifferentSaltAndIv(){val key="fixture-backup-password".toCharArray();val a=BackupCipher.encrypt(byteArrayOf(1,2,3),key);val b=BackupCipher.encrypt(byteArrayOf(1,2,3),key);assertFalse(a.contentEquals(b));assertArrayEquals(byteArrayOf(1,2,3),BackupCipher.decrypt(b,key))}
 @Test fun wrongPasswordAndTamperedPayloadCannotProduceAnArchive(){val key="fixture-backup-password".toCharArray();val value=BackupCipher.encrypt("private".toByteArray(),key);assertTrue(runCatching{BackupCipher.decrypt(value,"different-password".toCharArray())}.isFailure);value[value.lastIndex]=(value.last().toInt() xor 1).toByte();assertTrue(runCatching{BackupCipher.decrypt(value,key)}.isFailure)}
 @Test fun truncatedAndUnknownEnvelopeVersionsFailBeforeDecrypting(){for(v in listOf(byteArrayOf(),"MCBACKUP2".toByteArray(),ByteArray(52)))assertTrue(runCatching{BackupCipher.decrypt(v,"fixture-backup-password".toCharArray())}.isFailure)}
 @Test fun weakAndOversizedPasswordsFailClosed(){for(p in listOf("short","x".repeat(1025)))assertTrue(runCatching{BackupCipher.encrypt(byteArrayOf(1),p.toCharArray())}.isFailure)}
 @Test fun archiveRejectsTraversalAbsoluteBackslashAndUnknownDirectories(){for(name in listOf("../escape","/manifest.json","assets/custom-covers/../../escape.image","assets/custom-covers\\escape.image","assets/other/cover.image","assets/spoken-transcripts/a..txt"))assertTrue(name,runCatching{BackupArchive.unpack(zip("manifest.json" to root().toString(),name to "bad"))}.isFailure)}
 @Test fun archiveCannotIgnoreUndeclaredOrMissingAssets(){assertTrue(runCatching{BackupArchive.unpack(zip("manifest.json" to root().toString(),"assets/spoken-transcripts/a.txt" to "extra"))}.isFailure);val r=root().put("assets",JSONArray().put(JSONObject().put("path","spoken-transcripts/a.txt").put("sha256","a".repeat(64)).put("bytes",1)));assertTrue(runCatching{BackupArchive.unpack(zip("manifest.json" to r.toString()))}.isFailure)}
 @Test fun assetIntegrityMismatchFailsBeforeRestore(){val r=root().put("assets",JSONArray().put(JSONObject().put("path","spoken-transcripts/a.txt").put("sha256","a".repeat(64)).put("bytes",3)));assertTrue(runCatching{BackupArchive.unpack(zip("manifest.json" to r.toString(),"assets/spoken-transcripts/a.txt" to "bad"))}.isFailure)}
 @Test fun archiveExpansionIsBoundedEvenWhenHighlyCompressed(){val body="x".repeat(16*1024*1024+1);assertTrue(runCatching{BackupArchive.unpack(zip("manifest.json" to root().toString(),"assets/spoken-transcripts/a.txt" to body))}.isFailure)}
 @Test fun accountIdentityOriginAndCredentialsMustBeWellFormed(){for(change in listOf(JSONObject(root().getJSONArray("accounts").getJSONObject(0).toString()).put("url","file:///etc/passwd"),JSONObject(root().getJSONArray("accounts").getJSONObject(0).toString()).put("url","https://u:p@fixture.invalid"),JSONObject(root().getJSONArray("accounts").getJSONObject(0).toString()).put("accessToken","token\nheader"))){val r=root().put("accounts",JSONArray().put(change));assertTrue(runCatching{BackupData.validate(r)}.isFailure)};val r=root();r.getJSONArray("accounts").put(r.getJSONArray("accounts").get(0));assertTrue(runCatching{BackupData.validate(r)}.isFailure)}
 @Test fun importedFolderGrantsAndTransferJobsAreNotAccepted(){for(p in listOf("tree","jobs","items","playlists")){val r=root();r.getJSONObject("preferences").getJSONObject("media_downloads").put(p,"[]");assertTrue(runCatching{BackupData.validate(r)}.isFailure)}}
 @Test fun encryptedKeystoreAccountBlobsAreNotPortable(){val r=root();r.getJSONObject("preferences").getJSONObject("media_library").put("account.fixture","unportable");assertTrue(runCatching{BackupData.validate(r)}.isFailure)}
 @Test fun historyUsesBoundedNumbersValidJsonAndUniqueIdentities(){for(row in listOf(JSONArray(listOf("identity","{}",-1,0,0)),JSONArray(listOf("identity","invalid",0,0,0)),JSONArray(listOf("identity","{}",0,1.5,0)))){val r=root();r.getJSONObject("tables").getJSONArray("history").put(row);assertTrue(runCatching{BackupData.validate(r)}.isFailure)};val r=root();val rows=r.getJSONObject("tables").getJSONArray("history");rows.put(JSONArray(listOf("same","{}",3,1,1)));rows.put(JSONArray(listOf("same","{}",4,1,2)));assertTrue(runCatching{BackupData.validate(r)}.isFailure)}
 @Test fun restoreKeepsPersonalDataButDisablesAutomaticWork(){val r=root();val ui=JSONObject().put("material","glass").put("backgroundOfflineRules",true).put("cacheAhead",5).put("offlineRules",JSONArray().put(JSONObject().put("enabled",true))).put("mixRecipes",JSONArray().put(JSONObject().put("refresh","daily"))).put("personalPlaylists",JSONArray().put(JSONObject().put("name","Personal mix")));r.getJSONObject("preferences").getJSONObject("media_library").put("ui",ui.toString());val restored=BackupData.safeRestore(r);val prefs=JSONObject(restored.getJSONObject("preferences").getJSONObject("media_library").getString("ui"));assertFalse(prefs.getBoolean("backgroundOfflineRules"));assertEquals(0,prefs.getInt("cacheAhead"));assertEquals("frosted",prefs.getString("material"));assertFalse(prefs.getJSONArray("offlineRules").getJSONObject(0).getBoolean("enabled"));assertEquals("manual",prefs.getJSONArray("mixRecipes").getJSONObject(0).getString("refresh"));assertEquals("Personal mix",prefs.getJSONArray("personalPlaylists").getJSONObject(0).getString("name"));assertTrue(ui.getBoolean("backgroundOfflineRules"))}
}
